import { describe, it, expect } from 'vitest'
import { render, screen } from '@testing-library/react'
import { HomePage } from '../HomePage.js'

// Mock console.error to suppress React warnings in tests
vi.spyOn(console, 'error').mockImplementation(() => {})

describe('HomePage', () => {
  it('renders a welcome message with Pi POS branding', () => {
    render(<HomePage />)
    expect(screen.getByText(/Welcome to Pi POS/i)).toBeInTheDocument()
  })

  it('wraps content in a card layout', () => {
    const { container } = render(<HomePage />)
    // CardHeader renders a div with p-6 padding
    expect(container.querySelector('[class*="p-6"]')).toBeInTheDocument()
  })
})
